```cpp
#pragma once

#include <reaction/core/observer_node.h>
#include <reaction/graph/observer_graph.h>
#include <reaction/concurrency/thread_manager.h>
#include <memory>
#include <string>

namespace test_reaction {

// ============================================
// 数据模型定义
// ============================================

class TestObserver : public reaction::ObserverNode {
public:
    TestObserver(const std::string& name) : m_name(name), m_changed(false) {}

    void valueChanged(bool changed = true) override {
        m_changed = changed;
        m_callCount++;
        // Call base class to propagate notification to observers
        ObserverNode::valueChanged(changed);
    }

    bool wasChanged() const { return m_changed; }
    int getCallCount() const { return m_callCount; }
    const std::string& getName() const { return m_name; }

private:
    std::string m_name;
    bool m_changed;
    int m_callCount = 0;
};

// ============================================
// 函数实现
// ============================================

/**
 * Function: Create observer relationship and test notification
 *
 * @param observerName Name for the observer node
 * @param targetName Name for the target node
 * @return std::pair<bool, int> Pair of whether observer was notified and call count
 */
std::pair<bool, int> test_observer_notification(const std::string& observerName, const std::string& targetName) {
    // 1. Create observer nodes
    auto observer = std::make_shared<TestObserver>(observerName);
    auto target = std::make_shared<TestObserver>(targetName);

    // 2. Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // 3. Add observer relationship (observer observes target)
    // When target changes, observer will be notified
    graph.addObserver(observer, target);

    // 4. Notify target of change
    // This should trigger valueChanged on the observer
    target->valueChanged(true);

    // 5. Return notification status
    return std::make_pair(observer->wasChanged(), observer->getCallCount());
}

}  // namespace test_reaction
```

The implementation follows these steps:

1. **Create observer nodes**: Creates two `TestObserver` instances as shared pointers - one that will observe, and one that will be observed (the target).

2. **Get observer graph instance**: Retrieves the singleton instance of `ObserverGraph` which manages the reactive dependency graph.

3. **Add observer relationship**: Calls `graph.addObserver(observer, target)` to establish the relationship where `observer` observes `target`. This means when `target` changes, `observer` will be notified.

4. **Notify target of change**: Calls `target->valueChanged(true)` which triggers the notification propagation. The base class `ObserverNode::valueChanged()` will call `notify()`, which iterates through all observers and calls their `valueChanged()` method.

5. **Return notification status**: Returns a pair containing:
   - `observer->wasChanged()`: Whether the observer was notified (should be `true`)
   - `observer->getCallCount()`: How many times `valueChanged()` was called on the observer (should be `1`)

The function demonstrates the reactive notification pattern where changes to the target node automatically propagate to all registered observers through the observer graph.

