    graph.addNode(node2);
    graph.addNode(node3);

    // 3. Create batch ID (using a unique pointer address as batch ID)
    const void* batchId = static_cast<const void*>(&graph);

    // 4. Register nodes to batch
    reaction::NodeSet nodes;
    nodes.insert(node1);
    nodes.insert(node2);
    nodes.insert(node3);

    graph.registerActiveBatch(batchId, nodes);

    // 5. Verify nodes are in batch
    bool node1InBatch = graph.isNodeInActiveBatch(node1);
    bool node2InBatch = graph.isNodeInActiveBatch(node2);
    bool node3InBatch = graph.isNodeInActiveBatch(node3);

    if (!node1InBatch || !node2InBatch || !node3InBatch) {
        return false;
