```cpp
#pragma once

#include <reaction/core/observer_node.h>
#include <reaction/graph/observer_graph.h>
#include <memory>
#include <string>

namespace test_reaction {

// ============================================
// Data model definitions
// ============================================

class TestTransactionalObserver : public reaction::ObserverNode {
public:
    TestTransactionalObserver(const std::string& name) : m_name(name), m_changed(false) {}

    void valueChanged(bool changed = true) override {
        m_changed = changed;
        m_callCount++;
        // Call base class to propagate notification to observers
        ObserverNode::valueChanged(changed);
    }

    bool wasChanged() const { return m_changed; }
    int getCallCount() const { return m_callCount; }
    const std::string& getName() const { return m_name; }

    void reset() {
        m_changed = false;
        m_callCount = 0;
    }

private:
    std::string m_name;
    bool m_changed;
    int m_callCount = 0;
};

// ============================================
// Function implementations
// ============================================

/**
 * Function: Test transactional observer updates
 *
 * @param nodeName Name for the node to update
 * @return bool Whether transactional update succeeded (no cycle created)
 */
bool test_transactional_update(const std::string& nodeName) {
    // 1. Create observer nodes
    auto source = std::make_shared<TestTransactionalObserver>(nodeName + "_source");
    auto target = std::make_shared<TestTransactionalObserver>(nodeName + "_target");
    auto intermediate = std::make_shared<TestTransactionalObserver>(nodeName + "_intermediate");

    // 2. Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // Add nodes to the graph
    graph.addNode(source);
    graph.addNode(target);
    graph.addNode(intermediate);

    // Set node names for debugging
    graph.setName(source, nodeName + "_source");
    graph.setName(target, nodeName + "_target");
    graph.setName(intermediate, nodeName + "_intermediate");

    // 3. Set up initial relationship: source -> target
    source->updateObservers(target);

    // 4. Notify target and verify relationship works
    target->valueChanged(true);

    // Verify that source was notified
    if (!source->wasChanged()) {
        return false; // Relationship setup failed
    }

    // 5. Reset observer for next test
    source->reset();
    target->reset();

    // 6. Attempt transactional update that would create cycle
    // Try to make: source -> intermediate -> target (where source already -> target)
    // Then try to make target -> source, which would create a cycle
    bool cycleDetected = false;

    try {
        // This should throw DependencyCycleException since source already observes target
        source->updateObservers(target, intermediate);
        intermediate->updateObservers(target);

        // Now try to create a cycle: target -> source (this should fail)
        target->updateObservers(source);

    } catch (const reaction::DependencyCycleException& e) {
        // 7. Catch cycle exception if thrown
        cycleDetected = true;
    } catch (const std::exception& e) {
        // Unexpected exception
        return false;
    }

    // 8. Notify target again
    target->valueChanged(true);

    // 9. Verify original relationship is preserved
    // Source should still be observing target (from step 3)
    bool relationshipPreserved = source->wasChanged();

    // 10. Return success status
    // Success means: cycle was detected AND original relationship was preserved
    return cycleDetected && relationshipPreserved;
}

}  // namespace test_reaction
```

This implementation:

1. **Creates observer nodes** - Three `TestTransactionalObserver` instances (source, target, intermediate)
2. **Gets observer graph instance** - Uses the singleton pattern
3. **Sets up initial relationship** - Makes source observe target using `updateObservers()`
4. **Notifies target and verifies** - Changes target's value and checks that source was notified
5. **Resets observers** - Clears the changed flags for next test
6. **Attempts transactional update that creates cycle** - Tries to create a dependency cycle by making target observe source (when source already observes target)
7. **Catches cycle exception** - The `DependencyCycleException` should be thrown when trying to create the cycle
8. **Notifies target again** - Triggers another notification to verify the state
9. **Verifies original relationship is preserved** - Confirms that the source->target relationship still works (rollback was successful)
10. **Returns success status** - Returns true only if the cycle was detected AND the original relationship was preserved (indicating proper transactional rollback)

