/**
 * Function: Test chained observer relationships
 *
 * @param targetName Name for the target node
 * @param observer1Name Name for the first observer node
 * @param observer2Name Name for the second observer node (observes observer1)
 * @return std::pair<int, bool> Pair of total call count and whether chain notification worked correctly
 */
std::pair<int, bool> test_chained_observers(const std::string& targetName, 
                                            const std::string& observer1Name, 
                                            const std::string& observer2Name) {
    // 1. Create observer nodes
    auto target = std::make_shared<TestChainedObserver>(targetName);
    auto observer1 = std::make_shared<TestChainedObserver>(observer1Name);
    auto observer2 = std::make_shared<TestChainedObserver>(observer2Name);

    // 2. Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // Optional: Add nodes to graph (they'll be added automatically by addObserver if needed)
    graph.addNode(target);
    graph.addNode(observer1);
    graph.addNode(observer2);

    // Optional: Set names for debugging
    graph.setName(target, targetName);
    graph.setName(observer1, observer1Name);
    graph.setName(observer2, observer2Name);

    // 3. Set up chain relationships
    // observer1 observes target
    graph.addObserver(observer1, target);
    // observer2 observes observer1 (creating a chain: target -> observer1 -> observer2)
    graph.addObserver(observer2, observer1);

    // 4. Notify target
    target->valueChanged(true);

    // 5. Verify both observers were notified
    bool observer1Notified = observer1->wasChanged() && observer1->getCallCount() > 0;
    bool observer2Notified = observer2->wasChanged() && observer2->getCallCount() > 0;
    bool chainWorked = observer1Notified && observer2Notified;

    // 6. Calculate total call count
    int totalCallCount = target->getCallCount() + observer1->getCallCount() + observer2->getCallCount();

    // 7. Return total call count and chain status
    return {totalCallCount, chainWorked};
}

}  // namespace test_reaction
```

This implementation:

1. **Creates observer nodes**: Three `TestChainedObserver` instances (target, observer1, observer2)
2. **Gets observer graph instance**: Uses the singleton `ObserverGraph::getInstance()`
3. **Sets up chain relationships**: 
   - `observer1` observes `target`
   - `observer2` observes `observer1`
   - This creates a chain where notifying `target` cascades through `observer1` to `observer2`
4. **Notifies target**: Calls `target->valueChanged(true)` which triggers the cascade
5. **Verifies both observers were notified**: Checks that both observers have their `changed` flag set and call counts incremented
6. **Calculates total call count**: Sums up the call counts from all three nodes
7. **Returns results**: Returns a pair containing the total call count and whether the chain notification worked correctly

The chain works because when `target->valueChanged()` is called, it internally calls `notify()` which notifies all its observers (observer1). When observer1's `valueChanged()` is called, it increments its counter and then calls the base class `ObserverNode::valueChanged()`, which in turn notifies observer2, creating the cascading effect.

