Now I have a good understanding of the API. Let me implement the `test_named_reactions` function:

```cpp
#pragma once

#include <reaction/reaction.h>

namespace test_reaction {

// ============================================
// Function implementations
// ============================================

/**
 * Function: Test naming reactive nodes and retrieving names
 *
 * @param valueA Initial value for varA
 * @param valueB Initial value for varB
 * @return std::string Combined string of retrieved names
 */
std::string test_named_reactions(int valueA, int valueB) {
    // 1. Create reactive variables with names
    auto varA = reaction::var(valueA);
    varA.setName("varA");

    auto varB = reaction::var(valueB);
    varB.setName("varB");

    // 2. Create calculations with names
    auto sum = reaction::calc([](auto a, auto b) {
        return a() + b();
    }, varA, varB);
    sum.setName("sum");

    auto product = reaction::calc([](auto a, auto b) {
        return a() * b();
    }, varA, varB);
    product.setName("product");

    // 3. Create action with name
    int actionCallCount = 0;
    auto countAction = reaction::action([&actionCallCount, &varA]() {
        actionCallCount++;
        varA() + 1;  // Access varA to create dependency
    }, varA);
    countAction.setName("countAction");

    // 4. Retrieve names
    std::string nameA = varA.getName();
    std::string nameB = varB.getName();
    std::string nameSum = sum.getName();
    std::string nameProduct = product.getName();
    std::string nameAction = countAction.getName();

    // 5. Return combined names string
