49	    /**
50	     * @brief Bind all field nodes of an object to an input node.
51	     *
52	     * Adds observer edges from objPtr to each field node under the object ID.
53	     * @param id Object ID.
54	     * @param objPtr Source node.
55	     */
56	    void bindField(uint64_t id, const NodePtr &objPtr) {
57	        NodeSet nodesToBind;
58	        if (!m_fieldMap.contains(id)) {
59	            return;
60	        }
61	        nodesToBind = m_fieldMap[id]; // Copy the set
62	
63	        // Bind nodes
64	        for (auto &node : nodesToBind) {
65	            ObserverGraph::getInstance().addObserver(objPtr, node.lock());
66	        }
67	    }
