namespace test_reaction {

// ============================================
// Helper types
// ============================================

class FieldOwnerNode : public reaction::ObserverNode {
public:
    void valueChanged(bool changed = true) override {
        reaction::ObserverNode::valueChanged(changed);
        if (changed) {
            m_notificationCount++;
        }
    }

    int getNotificationCount() const {
        return m_notificationCount;
    }

private:
    int m_notificationCount = 0;
};

class ProfileFields : public reaction::FieldBase {
public:
    ProfileFields(int initialScore, bool initialStatus)
        : m_score(field(initialScore))
        , m_active(field(initialStatus)) {
    }

    reaction::Var<int>& score() {
        return m_score;
    }

    reaction::Var<bool>& active() {
        return m_active;
    }

private:
    reaction::Var<int> m_score;
    reaction::Var<bool> m_active;
};

struct FieldBindingResult {
    int notificationsAfterScoreUpdate;
    int notificationsAfterStatusUpdate;
};

// ============================================
// Function implementation
// ============================================

FieldBindingResult test_field_binding(int initialScore, int scoreDelta) {
    // 1. Create ProfileFields object
    ProfileFields profile(initialScore, true);

    // 2. Create FieldOwnerNode
    auto ownerNode = std::make_shared<FieldOwnerNode>();

    // 3. Get observer graph instance
    auto& observerGraph = reaction::ObserverGraph::getInstance();

    // 4. Register owner node
    observerGraph.addNode(ownerNode);

    // 5. Get field graph instance
    auto& fieldGraph = reaction::FieldGraph::getInstance();

    // 6. Bind fields to owner node
    fieldGraph.bindField(profile.getId(), ownerNode);

    // 7. Update score field
    profile.score().value(initialScore + scoreDelta);

    // 8. Record notification count after score update
    int notificationsAfterScoreUpdate = ownerNode->getNotificationCount();

    // 9. Update active field
    profile.active().value(false);

    // 10. Record notification count after status update
    int notificationsAfterStatusUpdate = ownerNode->getNotificationCount();

    // 11. Return notification counts
    return FieldBindingResult{
        notificationsAfterScoreUpdate,
        notificationsAfterStatusUpdate
    };
}

}  // namespace test_reaction
```

## Explanation

The implementation follows all the requested steps:

1. **ProfileFields class**: Inherits from `reaction::FieldBase` and creates two reactive fields (`m_score` and `m_active`) using the `field()` method from the base class. This ensures the fields are registered with the FieldGraph.

2. **FieldOwnerNode class**: Inherits from `reaction::ObserverNode` and overrides `valueChanged()` to count notifications. Each time a field changes and notifies this node, the counter increments.

3. **test_field_binding function**: 
   - Creates a `ProfileFields` object with initial values
   - Creates a `FieldOwnerNode` to track notifications
   - Registers the owner node with the `ObserverGraph`
   - Binds all fields from the profile to the owner node using `FieldGraph::bindField()`
   - Updates the score field and records the notification count
   - Updates the active field and records the final notification count
   - Returns both notification counts in a `FieldBindingResult` struct

The key insight is that `FieldGraph::bindField()` establishes observer relationships between the owner node and all field nodes associated with the profile's ID, so when either field is updated via `.value()`, the owner node gets notified through the `valueChanged()` callback.

