#include <reaction/reaction.h>
#include <string>

namespace test_reaction {

// NamedObserverNode implementation
class NamedObserverNode : public reaction::ObserverNode {
public:
    explicit NamedObserverNode(std::string name) : m_name(std::move(name)) {}

    const std::string& name() const { return m_name; }

private:
    std::string m_name;
};

// ObserverCollectionSummary structure
struct ObserverCollectionSummary {
    std::size_t totalObservers;
    bool containsDirectObserver;
    bool containsTransitiveObserver;
};

// Main test function
ObserverCollectionSummary test_observer_collection() {
    // Step 1: Create NamedObserverNode instances
    auto sourceNode = std::make_shared<NamedObserverNode>("source");
    auto directObserver = std::make_shared<NamedObserverNode>("direct");
    auto transitiveObserver = std::make_shared<NamedObserverNode>("transitive");

    // Step 2: Get observer graph instance
    auto& graph = reaction::ObserverGraph::getInstance();

    // Step 3: Register nodes in the graph
    graph.addNode(sourceNode);
    graph.addNode(directObserver);
    graph.addNode(transitiveObserver);

    // Step 4: Set up direct observer relationship
    // directObserver observes sourceNode
    graph.addObserver(directObserver, sourceNode);

    // Step 5: Set up transitive observer relationship
    // transitiveObserver observes directObserver (making it a transitive observer of sourceNode)
    graph.addObserver(transitiveObserver, directObserver);

    // Step 6: Create NodeSet to store collected observers
    reaction::NodeSet collectedObservers;

    // Step 7: Collect observers
    // This will collect both direct and transitive observers starting from sourceNode
    graph.collectObservers(sourceNode, collectedObservers);

    // Step 8: Check if direct observer is in collected set
    bool hasDirectObserver = false;
    for (const auto& weakObserver : collectedObservers) {
        if (auto observer = weakObserver.lock()) {
            if (observer == directObserver) {
                hasDirectObserver = true;
                break;
            }
        }
    }

    // Step 9: Check if transitive observer is in collected set
    bool hasTransitiveObserver = false;
    for (const auto& weakObserver : collectedObservers) {
        if (auto observer = weakObserver.lock()) {
            if (observer == transitiveObserver) {
                hasTransitiveObserver = true;
                break;
            }
        }
    }

    // Step 10: Return collection summary
    return ObserverCollectionSummary{
        collectedObservers.size(),
        hasDirectObserver,
        hasTransitiveObserver
    };
}

}  // namespace test_reaction

