21	namespace reaction {
22	
23	/**
24	 * @brief Enhanced comparison functor for ordering weak pointers to ObserverNodes by their depth.
25	 *
26	 * Provides safe comparison with null pointer checks and compile-time optimization.
27	 */
28	struct BatchCompare {
29	    /**
30	     * @brief Compare two weak pointers to ObserverNodes by their depth.
31	     * @param lhs Left-hand side weak pointer
32	     * @param rhs Right-hand side weak pointer
33	     * @return true if lhs's depth is less than rhs's depth
34	     */
35	    bool operator()(const NodeWeak &lhs, const NodeWeak &rhs) const noexcept {
36	        auto left = lhs.lock();
37	        auto right = rhs.lock();
38	
39	        // Handle null pointers safely
40	        if (!left && !right) return false;
41	        if (!left) return true; // null comes first
42	        if (!right) return false;
43	
44	        return left->m_depth.load(std::memory_order_relaxed) < right->m_depth.load(std::memory_order_relaxed);
45	    }
46	};
47	
48	/**
49	 * @brief Represents a batch operation that tracks and manages observer nodes.
50	 *
51	 * The Batch class executes a function while collecting all observer nodes
52	 * that are accessed during execution. It maintains these nodes and can
53	 * trigger value change notifications when the batch is executed.
54	 */
55	class Batch {
56	public:
57	    /**
58	     * @brief Construct a new Batch with the given function.
59	     *
60	     * @tparam F Type of the callable function
61	     * @param f Function to execute as part of this batch
62	     *
63	     * During construction:
64	     * 1. Sets up a BatchFunGuard to collect accessed observer nodes
65	     * 2. Executes the function
66	     * 3. Collects all observer nodes that were accessed (with caching)
67	     * 4. Registers this batch as active to prevent reset operations
68	     */
69	    template <InvocableType F>
70	    Batch(F &&f) : m_fun(std::forward<F>(f)), m_batchId(this) {
71	        BatchFunGuard g([this](const NodePtr &node) {
72	            // collectObservers now uses caching internally
73	            ObserverGraph::getInstance().collectObservers(node, m_observers);
74	        });
75	        std::invoke(f);
76	
77	        {
78	            for (auto &node : m_observers) {
79	                m_batchNodes.insert(node);
80	            }
81	        }
82	
83	        // Register this batch as active to protect nodes from reset operations
84	        ObserverGraph::getInstance().registerActiveBatch(m_batchId, m_observers);
85	    }
86	
87	    /**
88	     * @brief Destroy the Batch object.
89	     *
90	     * Unregisters this batch from active tracking if not already closed,
91	     * allowing reset operations on previously protected nodes.
92	     */
93	    ~Batch() {
94	        if (!m_isClosed) {
95	            // Only unregister if we haven't already closed
96	            m_isClosed = true;
97	            ObserverGraph::getInstance().unregisterActiveBatch(m_batchId);
98	        }
99	    }
100	
101	    // Disable copying and moving
102	    Batch(const Batch &) = delete;
103	    Batch(Batch &&) = delete;
104	
105	    /**
106	     * @brief Manually close the batch operation.
107	     *
108	     * This unregisters the batch from active tracking, allowing reset operations
109	     * on previously protected nodes. After calling close(), the batch is no longer
110	     * active and will not prevent reset operations.
111	     *
112	     * Calling close() multiple times is safe and has no effect after the first call.
113	     */
114	    void close() {
115	        if (!m_isClosed) {
116	            // Only unregister if we haven't already closed
117	            m_isClosed = true;
118	            ObserverGraph::getInstance().unregisterActiveBatch(m_batchId);
119	        }
120	    }
121	
122	    /**
123	     * @brief Check if the batch has been closed.
124	     *
125	     * @return true if the batch has been closed, false otherwise
126	     */
127	    [[nodiscard]] bool isClosed() const noexcept {
128	        return m_isClosed;
129	    }
130	
131	    /**
132	     * @brief Execute the batch operation.
133	     *
134	     * 1. Invokes the stored function
135	     * 2. Triggers valueChanged() on all collected observer nodes
136	     */
137	    void execute() {
138	        BatchExeGuard g(true);
139	        std::invoke(m_fun);
140	
141	        for (auto &node : m_batchNodes) {
142	            if (auto wp = node.lock()) [[likely]]
143	                wp->changedNoNotify();
144	        }
145	    }
146	
147	private:
148	    NodeSet m_observers;                                ///< Collection of observer nodes accessed during batch
149	    std::multiset<NodeWeak, BatchCompare> m_batchNodes; ///< Nodes tracked by this batch, ordered by depth
150	    std::function<void()> m_fun;                        ///< The function to execute for this batch
151	    const void *m_batchId;                              ///< Unique identifier for this batch instance
152	    bool m_isClosed{false};                             ///< Whether the batch has been manually closed
153	};
154	
155	} // namespace reaction

