11	// Test handling of repeated dependencies in the graph
12	TEST(BatchOperationsTest, TestRepeatDependency) {
13	    // ds → A, ds → a, A → a
14	    auto a = reaction::var(1).setName("a");
15	    auto b = reaction::var(2).setName("b");
16	
17	    int triggerCount = 0;
18	    auto dsA = reaction::calc([&]() { return a() + b(); }).setName("dsA");
19	
20	    auto dsB = reaction::calc([&]() {++triggerCount; return a() + dsA(); }).setName("dsB");
21	
22	    triggerCount = 0;
23	
24	    reaction::batchExecute([&]() { a.value(2); });
25	
26	    EXPECT_EQ(triggerCount, 1);
27	    EXPECT_EQ(dsB.get(), 6);
28	}
29	
30	// Test more complex repeated dependency scenarios
31	TEST(BatchOperationsTest, TestRepeatDependency2) {
32	    // ds → A, ds → B, ds → C, A → a, B → a
33	    int triggerCount = 0;
34	    auto a = reaction::var(1).setName("a");
35	    auto A = reaction::calc([&]() { return a() + 1; }).setName("A");
36	    auto B = reaction::calc([&]() { return a() + 2; }).setName("B");
37	    auto C = reaction::calc([&]() { return 5; }).setName("C");
38	    auto ds = reaction::calc([&]() { ++triggerCount; return A() + B() + C(); }).setName("ds");
39	
40	    auto ba = reaction::batch([&]() { a.value(2); });
41	
42	    triggerCount = 0;
43	    a.value(3);
44	    EXPECT_EQ(triggerCount, 2);
45	    EXPECT_EQ(ds.get(), 14);
46	
47	    triggerCount = 0;
48	    ba.execute();
49	    EXPECT_EQ(triggerCount, 1);
50	    EXPECT_EQ(ds.get(), 12);
51	
52	    triggerCount = 0;
53	    a.value(1);
54	    EXPECT_EQ(triggerCount, 2);
55	    EXPECT_EQ(ds.get(), 10);
56	}
57	
58	// Test deep nested dependency scenarios
59	TEST(BatchOperationsTest, TestRepeatDependency3) {
60	    // ds → A, ds → B, A → A1, A1 → A2, A2 → a, B → B1, B1 → a
61	    auto a = reaction::var(1).setName("a");
62	    auto b = reaction::var(1).setName("b");
63	
64	    int triggerCount = 0;
65	    auto A2 = reaction::calc([&]() { return a() * 2; }).setName("A2");
66	    auto A1 = reaction::calc([&]() { return A2() + 1; }).setName("A1");
67	    auto A = reaction::calc([&]() { return A1() - 1; }).setName("A");
68	
69	    auto B1 = reaction::calc([&]() { return a() - 1; }).setName("B1");
70	    auto B = reaction::calc([&]() { return B1() + 1; }).setName("B");
71	
72	    auto ds = reaction::calc([&]() { ++triggerCount; return A() + B(); }).setName("ds");
