#include "test_batch_execute_update.h"

namespace test_reaction {

BatchExecuteResult test_batch_execute_update(int baseValue, int deltaA, int deltaB) {
    // 1. Create reactive variable
    auto reactiveVar = reaction::var(baseValue);

    // 2. Create variable to track recomputation count
    int recomputeCount = 0;

    // 3. Create calculation that tracks recomputations
    auto calculation = reaction::calc([&]() {
        recomputeCount++;
        return reactiveVar();
    });

    // Force initial computation
    calculation.get();

    // Reset counter after initial computation
    recomputeCount = 0;

    // 4. Record recompute count before batch
    int recomputeCountBeforeBatch = recomputeCount;

    // 5. Execute batch updates
    reaction::batchExecute([&]() {
        // Update the reactive variable twice within the batch
        reactiveVar.value(baseValue + deltaA);
        reactiveVar.value(baseValue + deltaA + deltaB);
    });

    // 6. Record recompute count after batch
    int recomputeCountAfterBatch = recomputeCount;

    // 7. Get final value
    int finalValue = calculation.get();

    // 8. Return batch execution result
    return BatchExecuteResult{
        recomputeCountBeforeBatch,
        recomputeCountAfterBatch,
        finalValue
    };
}

}  // namespace test_reaction
```

## How It Works

1. **Creates a reactive variable** using `reaction::var(baseValue)`
2. **Tracks recomputation** by incrementing `recomputeCount` inside the `calc` lambda
3. **Creates a calculation** that depends on the reactive variable using `reaction::calc()`
4. **Records the count before batch** (should be 0 since we reset it after initial computation)
5. **Executes batch updates** using `reaction::batchExecute()` which performs two updates to the variable
6. **Records the count after batch** (should be 1 due to batching - only one recomputation despite two updates)
7. **Gets the final value** from the calculation
8. **Returns the result** with all three values

The key benefit of batch execution demonstrated here is that even though we update the reactive variable twice (`baseValue + deltaA` and then `baseValue + deltaA + deltaB`), the calculation only recomputes once after the batch completes, rather than recomputing twice. This is the core optimization that batch execution provides in reactive systems.

