8	#pragma once
9	
10	#include <functional>
11	#include <utility>
12	#include "reaction/concurrency/global_state.h"
13	#include "reaction/core/observer_node.h"
14	#include "reaction/core/types.h"
15	#include "reaction/core/concept.h"
16	#include "reaction/graph/observer_graph.h"
17	#include <atomic>
18	#include <iostream>
19	#include <set>
20	
21	namespace reaction {
22	
23	/**
24	 * @brief Enhanced comparison functor for ordering weak pointers to ObserverNodes by their depth.
25	 *
26	 * Provides safe comparison with null pointer checks and compile-time optimization.
27	 */
28	struct BatchCompare {
29	    /**
30	     * @brief Compare two weak pointers to ObserverNodes by their depth.
31	     * @param lhs Left-hand side weak pointer
32	     * @param rhs Right-hand side weak pointer
33	     * @return true if lhs's depth is less than rhs's depth
34	     */
35	    bool operator()(const NodeWeak &lhs, const NodeWeak &rhs) const noexcept {
36	        auto left = lhs.lock();
37	        auto right = rhs.lock();
38	
39	        // Handle null pointers safely
40	        if (!left && !right) return false;
41	        if (!left) return true; // null comes first
42	        if (!right) return false;
43	
44	        return left->m_depth.load(std::memory_order_relaxed) < right->m_depth.load(std::memory_order_relaxed);
45	    }
46	};
47	
48	/**
49	 * @brief Represents a batch operation that tracks and manages observer nodes.
50	 *
51	 * The Batch class executes a function while collecting all observer nodes
52	 * that are accessed during execution. It maintains these nodes and can
53	 * trigger value change notifications when the batch is executed.
54	 */
55	class Batch {
56	public:
57	    /**
58	     * @brief Construct a new Batch with the given function.
59	     *
60	     * @tparam F Type of the callable function
61	     * @param f Function to execute as part of this batch
62	     *
63	     * During construction:
64	     * 1. Sets up a BatchFunGuard to collect accessed observer nodes
65	     * 2. Executes the function
66	     * 3. Collects all observer nodes that were accessed (with caching)
67	     * 4. Registers this batch as active to prevent reset operations
68	     */
69	    template <InvocableType F>
70	    Batch(F &&f) : m_fun(std::forward<F>(f)), m_batchId(this) {
71	        BatchFunGuard g([this](const NodePtr &node) {
72	            // collectObservers now uses caching internally
73	            ObserverGraph::getInstance().collectObservers(node, m_observers);
74	        });
75	        std::invoke(f);
76	
77	        {
78	            for (auto &node : m_observers) {
79	                m_batchNodes.insert(node);
80	            }
81	        }
82	
83	        // Register this batch as active to protect nodes from reset operations
84	        ObserverGraph::getInstance().registerActiveBatch(m_batchId, m_observers);
85	    }
86	
87	    /**
88	     * @brief Destroy the Batch object.
89	     *
90	     * Unregisters this batch from active tracking if not already closed,
91	     * allowing reset operations on previously protected nodes.
92	     */
93	    ~Batch() {
94	        if (!m_isClosed) {
95	            // Only unregister if we haven't already closed
96	            m_isClosed = true;
97	            ObserverGraph::getInstance().unregisterActiveBatch(m_batchId);
98	        }
99	    }
100	
101	    // Disable copying and moving
102	    Batch(const Batch &) = delete;
103	    Batch(Batch &&) = delete;
104	
105	    /**
106	     * @brief Manually close the batch operation.
107	     *
108	     * This unregisters the batch from active tracking, allowing reset operations
109	     * on previously protected nodes. After calling close(), the batch is no longer
110	     * active and will not prevent reset operations.
111	     *
112	     * Calling close() multiple times is safe and has no effect after the first call.
113	     */
114	    void close() {
115	        if (!m_isClosed) {
116	            // Only unregister if we haven't already closed
117	            m_isClosed = true;
118	            ObserverGraph::getInstance().unregisterActiveBatch(m_batchId);
119	        }
120	    }
121	
122	    /**
123	     * @brief Check if the batch has been closed.
124	     *
125	     * @return true if the batch has been closed, false otherwise
126	     */
127	    [[nodiscard]] bool isClosed() const noexcept {
128	        return m_isClosed;
129	    }
130	
131	    /**
132	     * @brief Execute the batch operation.
133	     *
134	     * 1. Invokes the stored function
135	     * 2. Triggers valueChanged() on all collected observer nodes
136	     */
137	    void execute() {
138	        BatchExeGuard g(true);
139	        std::invoke(m_fun);
140	
141	        for (auto &node : m_batchNodes) {
142	            if (auto wp = node.lock()) [[likely]]
143	                wp->changedNoNotify();
144	        }
145	    }
146	
147	private:
148	    NodeSet m_observers;                                ///< Collection of observer nodes accessed during batch
149	    std::multiset<NodeWeak, BatchCompare> m_batchNodes; ///< Nodes tracked by this batch, ordered by depth
150	    std::function<void()> m_fun;                        ///< The function to execute for this batch
151	    const void *m_batchId;                              ///< Unique identifier for this batch instance
152	    bool m_isClosed{false};                             ///< Whether the batch has been manually closed
153	};
154	
155	} // namespace reaction

150	
151	    /// @brief Construct a React from shared pointer (usually internal use).
152	    explicit React(std::shared_ptr<react_type> ptr = nullptr) noexcept : m_weakPtr(ptr) {
153	        safeAddRef();
154	    }
155	
156	    /// @brief Destructor releases weak reference if still alive.
157	    ~React() {
158	        safeReleaseRef();
159	    }
160	
161	    /// @brief Copy constructor.
162	    React(const React &other) noexcept : m_weakPtr(other.m_weakPtr) {
163	        safeAddRef();
164	    }
165	
166	    /// @brief Move constructor.
167	    React(React &&other) noexcept : m_weakPtr(std::move(other.m_weakPtr)) {
168	        other.m_weakPtr.reset();
169	    }
170	
171	    /// @brief Copy assignment with reference count handling.
172	    React &operator=(const React &other) noexcept {
173	        if (this != &other) {
174	            safeReleaseRef();
175	            m_weakPtr = other.m_weakPtr;
176	            safeAddRef();
177	        }
178	        return *this;
179	    }
180	
181	    /// @brief Move assignment.
182	    React &operator=(React &&other) noexcept {
183	        if (this != &other) {
184	            safeReleaseRef();
185	            m_weakPtr = std::move(other.m_weakPtr);
186	            other.m_weakPtr.reset();
187	        }
188	        return *this;
189	    }
190	
191	    /// @brief Compare by internal pointer name (used in containers).
192	    bool operator<(const React &other) const {
193	        return getName() < other.getName();
194	    }
195	
196	    /// @brief Check equality by underlying object pointer.
197	    bool operator==(const React &other) const {
198	        return getPtr().get() == other.getPtr().get();
199	    }
200	
201	    /// @brief Pointer-like access to raw value.
202	    [[nodiscard]] auto operator->() const {
203	        return getPtr()->getRaw();
204	    }
205	
206	    /// @brief Checks if this React is valid (non-null).
207	    [[nodiscard]] explicit operator bool() const {
208	        return !m_weakPtr.expired();
209	    }
210	
211	    /**
212	     * @brief Value access operator.
213	     * If within a dependency registration scope, registers node.
214	     */
215	    [[nodiscard]] decltype(auto) operator()() const {
216	        REACTION_REGISTER_THREAD();
217	        if (g_reg_fun) {
218	            std::invoke(g_reg_fun, getPtr());
219	        }
220	        return get();
221	    }
222	
223	    /// @brief Returns the current value.
224	    [[nodiscard]] decltype(auto) get() const {
225	        REACTION_REGISTER_THREAD();
226	        return getPtr()->get();
227	    }
228	
229	    /// @brief Reset the expression with new source and dependencies.
230	    template <typename F, typename... A>
231	    React &reset(F &&f, A &&...args) {
232	        REACTION_REGISTER_THREAD();
233	        if (ThreadManager::getInstance().isThreadSafetyEnabled()) {
234	            // Use a dedicated mutex for reset operations
235	            ConditionalUniqueLock<ConditionalMutex> lock(m_resetMutex);
236	            auto ptr = m_weakPtr.lock();
237	            if (!ptr) [[unlikely]] {
238	                REACTION_THROW_NULL_POINTER("weak pointer expired during reset");
239	            }
240	            ptr->set(std::forward<F>(f), std::forward<A>(args)...);
241	        } else {
242	            // Single-threaded: direct access
243	            auto ptr = m_weakPtr.lock();
244	            if (!ptr) [[unlikely]] {
245	                REACTION_THROW_NULL_POINTER("weak pointer expired during reset");
246	            }
247	            ptr->set(std::forward<F>(f), std::forward<A>(args)...);
248	        }
249	        return *this;
250	    }
251	
252	    /// @brief Assigns a value (only if valid).
253	    template <typename T>
254	    React &value(T &&t) {
255	        REACTION_REGISTER_THREAD();
256	        if (g_batch_fun) {
257	            std::invoke(g_batch_fun, getPtr());
258	        } else {
259	            getPtr()->value(std::forward<T>(t));
260	        }
261	        return *this;
262	    }
263	
264	    /// @brief Apply a filter to this React node.
265	    template <typename F, typename... A>
266	    React &filter(F &&f, A &&...args) {
267	        getPtr()->filter(std::forward<F>(f), std::forward<A>(args)...);
268	        return *this;
269	    }
270	
271	    /// @brief Closes this reactive node.
272	    React &close() {
273	        REACTION_REGISTER_THREAD();
274	        getPtr()->close();
275	        return *this;
276	    }
277	
278	    /// @brief Assign a human-readable name for debugging/tracing.
279	    React &setName(const std::string &name) {
280	        ObserverGraph::getInstance().setName(getPtr(), name);
281	        return *this;
282	    }
283	
284	    /// @brief Get the name assigned to this node.
285	    [[nodiscard]] std::string getName() const {
286	        return ObserverGraph::getInstance().getName(getPtr());
287	    }
288	
289	    // ==================== Compound Assignment Operators ====================
