 *
 * This software is released under the MIT License.
 * See the LICENSE file in the project root for full details.
 */

#include "test_last_handle_restore.h"

namespace test_reaction {

LastHandleSnapshot test_last_handle_restore(int initialValue, int updatedValue) {
    LastHandleSnapshot snapshot;

    // Step 1: Create a reactive variable
    auto source = reaction::var(initialValue);

    // Step 2: Create a calculation with LastHandle policy
    // The calculation depends on the source variable
    auto calculation = reaction::calc<reaction::ChangeTrig, reaction::LastHandle>(
        [](int val) { return val * 2; },
        source
    );

    // Step 3: Get the initial result
    snapshot.initialValue = calculation.get();

    // Step 4: Update the source variable
    source.value(updatedValue);

    // Step 5: Get the updated result
    snapshot.afterUpdate = calculation.get();

    // Step 6: Close the source node
    // This triggers the LastHandle invalidation policy
    // which captures the last value and replaces the expression
    // with a constant function returning that value
    source.close();

    // Step 7: Get the result after source close
    // The calculation should still return the last captured value
    // even though the source is closed
    snapshot.afterSourceClose = calculation.get();

    // Step 8: Return last handle snapshot
    return snapshot;
}

}  // namespace test_reaction
```

## Explanation

This implementation demonstrates the **LastHandle** invalidation policy behavior:

1. **Create a reactive variable**: `source` holds the initial value
2. **Create a calculation with LastHandle**: The calculation multiplies the source value by 2 and uses the `LastHandle` invalidation policy
3. **Initial result**: Gets the calculated value (initialValue * 2)
4. **Update source**: Changes the source value to `updatedValue`
5. **Updated result**: Gets the new calculated value (updatedValue * 2)
6. **Close source**: When the source node is closed, the `LastHandle` policy is triggered, which:
   - Captures the last computed value from the calculation
   - Replaces the calculation's expression with a constant function that returns this captured value
7. **After close result**: Even though the source is closed, the calculation can still return the last value it had before the source was closed
8. **Return snapshot**: Returns all three values for verification

The key insight is that `LastHandle` preserves the last value of a calculation even after its dependencies are closed, by converting the dynamic calculation into a constant value function.

