15	namespace reaction {
16	
17	/**
18	 * @brief Base exception class for all reaction framework exceptions.
19	 *
20	 * This class provides common functionality for all exceptions thrown by
21	 * the reaction framework, including error codes, context information,
22	 * and debugging support.
23	 */
24	class ReactionException : public std::runtime_error {
25	public:
26	    /**
27	     * @brief Error codes for different types of exceptions.
28	     */
29	    enum class ErrorCode {
30	        UNKNOWN = 0,
31	        DEPENDENCY_CYCLE,
32	        SELF_OBSERVATION,
33	        NULL_POINTER_ACCESS,
34	        RESOURCE_NOT_INITIALIZED,
35	        TYPE_MISMATCH,
36	        INVALID_STATE,
37	        THREAD_SAFETY_VIOLATION,
38	        BATCH_OPERATION_CONFLICT,
39	        MEMORY_ALLOCATION_FAILURE,
40	        GRAPH_CORRUPTION,
41	        OBSERVER_LIMIT_EXCEEDED
42	    };
43	
44	    /**
45	     * @brief Construct a ReactionException with message and error code.
46	     *
47	     * @param message Descriptive error message
48	     * @param code Error code identifying the exception type
49	     * @param file Source file where the exception occurred
50	     * @param line Line number where the exception occurred
51	     * @param function Function name where the exception occurred
52	     */
53	    ReactionException(const std::string &message,
54	        ErrorCode code = ErrorCode::UNKNOWN,
55	        const std::string &file = "",
56	        int line = 0,
57	        const std::string &function = "")
58	        : std::runtime_error(formatMessage(message, code, file, line, function)), m_errorCode(code), m_file(file), m_line(line), m_function(function), m_originalMessage(message) {
59	    }
60	
61	    /**
62	     * @brief Get the error code associated with this exception.
63	     * @return ErrorCode identifying the type of error
64	     */
65	    ErrorCode getErrorCode() const noexcept {
66	        return m_errorCode;
67	    }
68	
69	    /**
70	     * @brief Get the source file where the exception occurred.
71	     * @return File path as string
72	     */
73	    const std::string &getFile() const noexcept {
74	        return m_file;
75	    }
76	
77	    /**
78	     * @brief Get the line number where the exception occurred.
79	     * @return Line number
80	     */
81	    int getLine() const noexcept {
82	        return m_line;
83	    }
84	
85	    /**
86	     * @brief Get the function name where the exception occurred.
87	     * @return Function name as string
88	     */
89	    const std::string &getFunction() const noexcept {
90	        return m_function;
91	    }
92	
93	    /**
94	     * @brief Get the original error message without formatting.
95	     * @return Original error message
96	     */
97	    const std::string &getOriginalMessage() const noexcept {
98	        return m_originalMessage;
99	    }
100	
101	    /**
102	     * @brief Convert error code to human-readable string.
103	     * @param code Error code to convert
104	     * @return String representation of the error code
105	     */
106	    static std::string errorCodeToString(ErrorCode code) {
107	        switch (code) {
108	        case ErrorCode::DEPENDENCY_CYCLE:
109	            return "DEPENDENCY_CYCLE";
110	        case ErrorCode::SELF_OBSERVATION:
111	            return "SELF_OBSERVATION";
112	        case ErrorCode::NULL_POINTER_ACCESS:
113	            return "NULL_POINTER_ACCESS";
114	        case ErrorCode::RESOURCE_NOT_INITIALIZED:
115	            return "RESOURCE_NOT_INITIALIZED";
116	        case ErrorCode::TYPE_MISMATCH:
117	            return "TYPE_MISMATCH";
118	        case ErrorCode::INVALID_STATE:
119	            return "INVALID_STATE";
120	        case ErrorCode::THREAD_SAFETY_VIOLATION:
121	            return "THREAD_SAFETY_VIOLATION";
122	        case ErrorCode::BATCH_OPERATION_CONFLICT:
123	            return "BATCH_OPERATION_CONFLICT";
124	        case ErrorCode::MEMORY_ALLOCATION_FAILURE:
125	            return "MEMORY_ALLOCATION_FAILURE";
126	        case ErrorCode::GRAPH_CORRUPTION:
127	            return "GRAPH_CORRUPTION";
128	        case ErrorCode::OBSERVER_LIMIT_EXCEEDED:
129	            return "OBSERVER_LIMIT_EXCEEDED";
130	        default:
131	            return "UNKNOWN";
132	        }
133	    }
134	
135	protected:
136	    /**
137	     * @brief Format exception message with additional context information.
138	     */
139	    static std::string formatMessage(const std::string &message,
140	        ErrorCode code,
141	        const std::string &file,
142	        int line,
143	        const std::string &function) {
144	        std::ostringstream oss;
145	        oss << "[" << errorCodeToString(code) << "] " << message;
146	
147	        if (!file.empty() || line > 0 || !function.empty()) {
148	            oss << " (";
149	            if (!function.empty()) {
150	                oss << "in " << function;
151	            }
152	            if (!file.empty()) {
153	                oss << " at " << file;
154	                if (line > 0) {
155	                    oss << ":" << line;
156	                }
157	            }
158	            oss << ")";
159	        }
160	
161	        return oss.str();
162	    }
163	
164	private:
165	    ErrorCode m_errorCode;
166	    std::string m_file;
167	    int m_line;
168	    std::string m_function;
169	    std::string m_originalMessage;
170	};
