28	namespace reaction {
29	
30	// Forward declarations
31	class ObserverNode;
32	using NodePtr = std::shared_ptr<ObserverNode>;
33	
34	/**
35	 * @brief Manages the graph structure of reactive observers and dependencies.
36	 *
37	 * This singleton class is responsible for:
38	 * - Adding and removing nodes
39	 * - Managing observer/dependent relationships
40	 * - Detecting cycles
41	 */
42	class ObserverGraph {
43	public:
44	    /**
45	     * @brief Get the singleton instance of the graph.
46	     * @return ObserverGraph& singleton reference.
47	     */
48	    [[nodiscard]] static ObserverGraph &getInstance() noexcept {
49	        static ObserverGraph instance;
50	        return instance;
51	    }
52	
53	    /**
54	     * @brief Add a new node into the graph.
55	     * @param node Node to add.
56	     */
57	    void addNode(const NodePtr &node) noexcept;
58	
59	    /**
60	     * @brief Add an observer relationship (source observes target).
61	     *
62	     * @param source The observing node.
63	     * @param target The node being observed.
64	     * @throws std::runtime_error if a cycle or self-observation is detected.
65	     */
66	    void addObserver(const NodePtr &source, const NodePtr &target) {
67	        REACTION_REGISTER_THREAD();
68	        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
69	
70	        if (source == target) {
71	            REACTION_THROW_SELF_OBSERVATION(getNameInternal(source));
72	        }
73	
74	        // Check if both nodes exist in the graph first
75	        if (!m_dependentList.contains(source) || !m_observerList.contains(target)) {
76	            // If nodes don't exist, add them first (without taking locks since we already have one)
77	            if (!m_dependentList.contains(source)) {
78	                addNodeInternal(source);
79	            }
80	            if (!m_observerList.contains(target)) {
81	                addNodeInternal(target);
82	            }
83	        }
84	
85	        if (hasCycle(source, target)) {
86	            REACTION_THROW_DEPENDENCY_CYCLE(getNameInternal(source), getNameInternal(target));
87	        }
88	
89	        m_dependentList.at(source).insert(target);
90	        {
91	            ConditionalUniqueLock<ConditionalSharedMutex> targetLock(target->m_observersMutex);
92	            target->m_observers.insert(source);
93	        }
94	
95	        // Invalidate all caches due to graph structure change
96	        m_graphCache.invalidateAll();
97	        m_cycleCache.invalidateAll();
98	        m_metricsCache.invalidateAll();
99	    }
100	
101	    /**
102	     * @brief Register a batch operation that affects specific nodes.
103	     *
104	     * This method tracks which nodes are currently involved in active batch operations.
105	     * Reset operations on these nodes will be prevented or delayed.
106	     *
107	     * @param batchId Unique identifier for the batch operation
108	     * @param nodes Set of nodes affected by this batch
109	     */
110	    void registerActiveBatch(const void *batchId, const NodeSet &nodes) {
111	        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
112	        for (const auto &nodeWeak : nodes) {
113	            if (auto node = nodeWeak.lock()) {
114	                m_activeBatchNodes[node].insert(batchId);
115	            }
116	        }
117	        m_activeBatchIds.insert(batchId);
118	    }
119	
120	    /**
121	     * @brief Unregister a batch operation.
122	     *
123	     * Removes the batch from active tracking and allows reset operations
124	     * on previously protected nodes.
125	     *
126	     * @param batchId Unique identifier for the batch operation
127	     */
128	    void unregisterActiveBatch(const void *batchId) {
129	        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
130	        m_activeBatchIds.erase(batchId);
131	
132	        // Remove this batch from all node tracking
133	        for (auto it = m_activeBatchNodes.begin(); it != m_activeBatchNodes.end();) {
134	            it->second.erase(batchId);
135	            if (it->second.empty()) {
136	                it = m_activeBatchNodes.erase(it);
137	            } else {
138	                ++it;
139	            }
140	        }
141	    }
142	
143	    /**
144	     * @brief Check if a node is currently involved in any active batch operation.
145	     *
146	     * @param node The node to check
147	     * @return true if the node is in an active batch, false otherwise
148	     */
149	    bool isNodeInActiveBatch(const NodePtr &node) const {
150	        ConditionalSharedLock<ConditionalSharedMutex> lock(m_graphMutex);
151	        auto it = m_activeBatchNodes.find(node);
152	        return it != m_activeBatchNodes.end() && !it->second.empty();
153	    }
154	
155	    /**
156	     * @brief Reset all dependencies for a node.
157	     *
158	     * This clears dependencies and cleans up related data structures.
159	     * @param node The node to reset.
160	     * @throws std::runtime_error if the node is currently involved in an active batch operation
161	     */
162	    void resetNode(const NodePtr &node) {
163	        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
164	        // Check if node exists in dependent list first
165	        if (m_dependentList.contains(node)) {
166	            for (auto dep : m_dependentList[node]) {
167	                if (auto locked_dep = dep.lock()) {
168	                    if (m_observerList.contains(locked_dep)) {
169	                        ConditionalUniqueLock<ConditionalSharedMutex> observerLock(locked_dep->m_observersMutex);
170	                        m_observerList.at(locked_dep).get().erase(node);
171	                    }
172	                }
173	            }
174	            m_dependentList.at(node).clear();
175	        }
176	
177	        // Invalidate all caches due to graph structure change
178	        m_graphCache.invalidateAll();
179	        m_cycleCache.invalidateAll();
180	        m_metricsCache.invalidateAll();
181	    }
182	
183	    /**
184	     * @brief Transactional update of all observer dependencies.
185	     *
186	     * This method ensures atomicity: either all observer updates succeed,
187	     * or the original state is completely restored on failure.
188	     *
189	     * @tparam Args Parameter pack for node pointers.
190	     * @param node The node whose observers are being updated.
191	     * @param args New nodes to observe.
192	     */
193	    template <typename... Args>
194	    void updateObserversTransactional(const NodePtr &node, Args &&...args) {
195	        if (!node) return;
196	
197	        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
198	
199	        // Step 1: Save current state for rollback
200	        NodeSet originalDependents;
201	        if (m_dependentList.contains(node)) {
202	            originalDependents = m_dependentList[node];
203	        }
204	
205	        // Step 2: Reset current dependencies
206	        resetNodeInternal(node);
207	
208	        // Step 3: Try to add new observers
209	        try {
210	            // Add each observer using fold expression
211	            ((args ? addObserverInternal(node, args) : void()), ...);
212	
213	        } catch (const std::exception &) {
214	            // Step 4: Rollback - restore original dependencies
215	            resetNodeInternal(node); // Clear any partially added observers
216	
217	            // Restore original dependencies
218	            for (auto &dep : originalDependents) {
219	                if (auto locked_dep = dep.lock()) {
220	                    addObserverInternal(node, locked_dep);
221	                }
222	            }
223	
224	            throw; // Re-throw the original exception
225	        }
226	    }
227	
228	    /**
229	     * @brief Transactional reset and update for a node's state.
230	     *
231	     * This method saves the current observer state, allows external operations,
232	     * and provides rollback capability if needed.
233	     *
234	     * @param node The node to save state for.
235	     * @return A rollback function that can restore the original state.
236	     */
237	    std::function<void()> saveNodeStateForRollback(const NodePtr &node) {
238	        if (!node) return []() {};
239	
240	        ConditionalSharedLock<ConditionalSharedMutex> readLock(m_graphMutex);
241	        // Save current state
242	        NodeSet originalDependents;
243	        if (m_dependentList.contains(node)) {
244	            originalDependents = m_dependentList[node];
245	        }
246	        // readLock will be automatically unlocked when it goes out of scope
247	
248	        // Return rollback function
249	        return [this, node, originalDependents = std::move(originalDependents)]() mutable {
250	            ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
251	            // Reset current dependencies
252	            resetNodeInternal(node);
253	
254	            // Restore original dependencies
255	            for (auto &dep : originalDependents) {
256	                if (auto locked_dep = dep.lock()) {
257	                    addObserverInternal(node, locked_dep);
258	                }
259	            }
260	        };
261	    }
262	
263	    /**
264	     * @brief Recursively remove a node and its downstream dependents.
265	     *
266	     * This is a cascade delete for the node and all nodes depending on it.
267	     * @param node Node to remove.
268	     */
269	    void closeNode(const NodePtr &node) {
270	        if (!node) return;
271	
272	        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
273	        NodeSet closedNodes;
274	        cascadeCloseDependents(node, closedNodes);
275	    }
276	
277	    void collectObservers(const NodePtr &node, NodeSet &observers, uint16_t depth) noexcept;
278	
279	    /**
280	     * @brief Set a human-readable name for a node.
281	     *
282	     * Names are used for logging and debugging.
283	     * @param node Node to name.
284	     * @param name Assigned name.
285	     */
286	    void setName(const NodePtr &node, const std::string &name) noexcept {
287	        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
288	        m_nameList.insert({node, name});
289	    }
290	
291	    /**
292	     * @brief Get the name of a node.
293	     * @param node Node to query.
294	     * @return Human-readable name or empty string if not found.
295	     */
296	    [[nodiscard]] std::string getName(const NodePtr &node) noexcept {
297	        ConditionalSharedLock<ConditionalSharedMutex> lock(m_graphMutex);
298	        return getNameInternal(node);
299	    }
300	
301	    /**
302	     * @brief Trigger cleanup of all cache subsystems.
303	     *
304	     * This method is called by the cache manager to perform periodic
305	     * cleanup of expired cache entries across all caches.
306	     */
307	    void triggerCacheCleanup() noexcept {
308	        m_graphCache.triggerCleanup();
309	        m_cycleCache.triggerCleanup();
310	        m_metricsCache.triggerCleanup();
311	    }
312	
313	    /**
314	     * @brief Get cache statistics from all subsystems.
315	     */
316	    struct CacheStats {
317	        GraphTraversalCache::Stats graphStats;
318	        CycleDetectionCache::Stats cycleStats;
319	        NodeMetricsCache::Stats metricsStats;
320	
321	        CacheStats(const GraphTraversalCache::Stats &gStats,
322	            const CycleDetectionCache::Stats &cStats,
323	            const NodeMetricsCache::Stats &mStats)
324	            : graphStats(gStats), cycleStats(cStats), metricsStats(mStats) {}
325	    };
326	
327	    CacheStats getCacheStats() const noexcept {
328	        auto graphStats = m_graphCache.getStats();
329	        auto cycleStats = m_cycleCache.getStats();
330	        auto metricsStats = m_metricsCache.getStats();
331	        return CacheStats{graphStats, cycleStats, metricsStats};
332	    }
333	
334	private:
335	    ObserverGraph() {}
336	
337	    mutable ConditionalSharedMutex m_graphMutex; ///< Conditional mutex for thread-safe graph operations.
338	
339	    /**
340	     * @brief Internal get name operation without locking.
341	     * Should only be called when the graph mutex is already held.
342	     * @param node Node to query.
343	     * @return Human-readable name or empty string if not found.
344	     */
345	    [[nodiscard]] std::string getNameInternal(const NodePtr &node) noexcept {
346	        if (m_nameList.contains(node)) {
347	            return m_nameList[node];
348	        } else {
349	            return "";
350	        }
351	    }
352	
353	    /**
354	     * @brief Internal add node operation without locking.
355	     * Should only be called when the graph mutex is already held.
356	     * @param node Node to add.
357	     */
358	    void addNodeInternal(const NodePtr &node) noexcept;
359	
360	    /**
361	     * @brief Helper function to recursively close dependents of a node.
362	     * @param node Starting node.
363	     * @param closedNodes Set of already closed nodes to avoid cycles.
364	     */
365	    void cascadeCloseDependents(const NodePtr &node, NodeSet &closedNodes) {
366	        if (!node || closedNodes.contains(node)) return;
367	        closedNodes.insert(node);
368	
369	        // Check if node exists in observer list to avoid at() exceptions
370	        if (m_observerList.contains(node)) {
371	            auto observerLists = m_observerList.at(node).get();
372	
373	            for (auto &ob : observerLists) {
374	                cascadeCloseDependents(ob.lock(), closedNodes);
375	            }
376	        }
377	
378	        closeNodeInternal(node);
379	    }
380	
381	    /**
382	     * @brief Internal close operation for a node.
383	     *
384	     * Removes node from all internal data structures.
385	     * @param node Node to close.
386	     */
387	    void closeNodeInternal(const NodePtr &node) {
388	        if (!node) return;
389	
390	        // Clean up dependent relationships - this node observes others
391	        if (m_dependentList.contains(node)) {
392	            for (auto dep : m_dependentList[node]) {
393	                if (auto locked_dep = dep.lock()) {
394	                    if (m_observerList.contains(locked_dep)) {
395	                        ConditionalUniqueLock<ConditionalSharedMutex> observerLock(locked_dep->m_observersMutex);
396	                        m_observerList.at(locked_dep).get().erase(node);
397	                    }
398	                }
399	            }
400	            m_dependentList.erase(node);
401	        }
402	
403	        // Clean up observer relationships - others observe this node
404	        if (m_observerList.contains(node)) {
405	            for (auto &ob : m_observerList.at(node).get()) {
406	                if (auto locked_ob = ob.lock()) {
407	                    if (m_dependentList.contains(locked_ob)) {
408	                        m_dependentList.at(locked_ob).erase(node);
409	                    }
410	                }
411	            }
412	            m_observerList.erase(node);
413	        }
414	
415	        // Remove name mapping
416	        m_nameList.erase(node);
417	    }
418	
419	    /**
420	     * @brief Detect whether adding an observer relationship would cause a cycle.
421	     *
422	     * Uses caching to avoid expensive DFS traversals for previously checked node pairs.
423	     * @param source The observing node.
424	     * @param target The node being observed.
425	     * @return true if a cycle would be created, false otherwise.
426	     */
427	    [[nodiscard]] bool hasCycle(const NodePtr &source, const NodePtr &target) {
428	        // Check if nodes exist in the graph first to avoid at() exceptions
429	        if (!m_dependentList.contains(source) || !m_observerList.contains(target)) {
430	            return false; // Nodes don't exist, no cycle possible
431	        }
432	
433	        // Try to get cached result first
434	        const bool *cachedResult = m_cycleCache.getCachedCycleResult(source, target);
435	        if (cachedResult) {
436	            return *cachedResult;
437	        }
438	
439	        // Cache miss - perform DFS and cache the result
440	        m_dependentList.at(source).insert(target);
441	        {
442	            ConditionalUniqueLock<ConditionalSharedMutex> targetLock(target->m_observersMutex);
443	            target->m_observers.insert(source);
444	        }
445	
446	        NodeSet visited;
447	        NodeSet recursionStack;
448	        bool hasCycleResult = dfs(source, visited, recursionStack);
449	
450	        m_dependentList.at(source).erase(target);
451	        {
452	            ConditionalUniqueLock<ConditionalSharedMutex> targetLock(target->m_observersMutex);
453	            target->m_observers.erase(source);
454	        }
455	
456	        // Cache the result for future use
457	        m_cycleCache.cacheCycleResult(source, target, hasCycleResult);
458	
459	        return hasCycleResult;
460	    }
461	
462	    /**
463	     * @brief DFS traversal for cycle detection.
464	     * @param node Current node in DFS.
465	     * @param visited Set of visited nodes.
466	     * @param recursionStack Stack of nodes in current DFS path.
467	     * @return true if cycle detected, false otherwise.
468	     */
469	    [[nodiscard]] bool dfs(const NodePtr &node, NodeSet &visited, NodeSet &recursionStack) {
470	        if (recursionStack.contains(node)) return true;
471	        if (visited.contains(node)) return false;
472	
473	        visited.insert(node);
474	        recursionStack.insert(node);
475	
476	        // Check if node exists in dependent list to avoid at() exceptions
477	        if (m_dependentList.contains(node)) {
478	            for (auto neighbor : m_dependentList.at(node)) {
479	                if (auto locked_neighbor = neighbor.lock()) {
480	                    if (dfs(locked_neighbor, visited, recursionStack))
481	                        return true;
482	                }
483	            }
484	        }
485	
486	        recursionStack.erase(node);
487	        return false;
488	    }
489	
490	    /**
491	     * @brief Internal reset operation without locking.
492	     * Should only be called when graph mutex is already held.
493	     * @param node The node to reset.
494	     */
495	    void resetNodeInternal(const NodePtr &node) {
496	        if (!node) return;
497	
498	        // Clean up dependent relationships - this node observes others
499	        if (m_dependentList.contains(node)) {
500	            for (auto dep : m_dependentList[node]) {
501	                if (auto locked_dep = dep.lock()) {
502	                    if (m_observerList.contains(locked_dep)) {
503	                        // Take the node's observer mutex before modifying its observer set
504	                        ConditionalUniqueLock<ConditionalSharedMutex> observerLock(locked_dep->m_observersMutex);
505	                        m_observerList.at(locked_dep).get().erase(node);
506	                    }
507	                }
508	            }
509	            m_dependentList.at(node).clear();
510	        }
511	    }
512	
513	    /**
514	     * @brief Internal add observer operation without locking.
515	     * Should only be called when graph mutex is already held.
516	     * @param source The observing node.
517	     * @param target The node being observed.
518	     */
519	    void addObserverInternal(const NodePtr &source, const NodePtr &target) {
520	        if (source == target) {
521	            REACTION_THROW_SELF_OBSERVATION(getNameInternal(source));
522	        }
523	
524	        // Ensure both nodes exist in the graph
525	        if (!m_dependentList.contains(source)) {
526	            addNodeInternal(source);
527	        }
