16	/**
17	 * @brief Manages object field bindings in the reactive graph.
18	 *
19	 * Used to track field-depth reactive nodes for specific object IDs.
20	 */
21	class FieldGraph {
22	public:
23	    /**
24	     * @brief Get singleton instance.
25	     * @return FieldGraph& singleton reference.
26	     */
27	    [[nodiscard]] static FieldGraph &getInstance() noexcept {
28	        static FieldGraph instance;
29	        return instance;
30	    }
31	
32	    /**
33	     * @brief Register a node under an object ID.
34	     * @param id Object ID.
35	     * @param node Node pointer.
36	     */
37	    void addObj(uint64_t id, const NodePtr &node) noexcept {
38	        m_fieldMap[id].insert(node);
39	    }
40	
41	    /**
42	     * @brief Remove all fields for an object.
43	     * @param id Object ID.
44	     */
45	    void deleteObj(uint64_t id) noexcept {
46	        m_fieldMap.erase(id);
47	    }
48	
49	    /**
50	     * @brief Bind all field nodes of an object to an input node.
51	     *
52	     * Adds observer edges from objPtr to each field node under the object ID.
53	     * @param id Object ID.
54	     * @param objPtr Source node.
55	     */
56	    void bindField(uint64_t id, const NodePtr &objPtr) {
57	        NodeSet nodesToBind;
58	        if (!m_fieldMap.contains(id)) {
59	            return;
60	        }
61	        nodesToBind = m_fieldMap[id]; // Copy the set
62	
63	        // Bind nodes
64	        for (auto &node : nodesToBind) {
65	            ObserverGraph::getInstance().addObserver(objPtr, node.lock());
66	        }
67	    }
68	
69	private:
70	    FieldGraph() {}
71	    std::unordered_map<uint64_t, NodeSet> m_fieldMap; ///< Map from object ID to its field nodes.
72	};
73	
74	} // namespace reaction
