19	/**
20	 * @brief Small Buffer Optimization (SBO) configuration constants.
21	 */
22	struct SBOConfig {
23	    // Size thresholds for SBO decision making
24	    static constexpr size_t ALWAYS_SBO_SIZE = 16;    ///< Always use SBO for types ≤ 16 bytes
25	    static constexpr size_t CONDITIONAL_SBO_SIZE = 32; ///< Conditional SBO for 17-32 bytes
26	    static constexpr size_t MAX_SBO_SIZE = 64;        ///< Maximum size for SBO consideration
27	
28	    // Stack usage limits per thread
29	    static constexpr size_t MAX_SBO_STACK_USAGE = 64 * 1024; ///< 64KB max SBO stack usage per thread
30	    static constexpr size_t STACK_USAGE_WARNING = 32 * 1024; ///< Warning threshold for stack usage
31	
32	    // Alignment requirements
33	    static constexpr size_t MAX_SBO_ALIGNMENT = alignof(std::max_align_t);
34	};
35	
36	/**
37	 * @brief Type traits for SBO eligibility checking.
38	 */
39	template<typename T>
40	struct SBOTraits {
41	    static constexpr bool is_small_enough = sizeof(T) <= SBOConfig::MAX_SBO_SIZE;
42	    static constexpr bool is_aligned_properly = alignof(T) <= SBOConfig::MAX_SBO_ALIGNMENT;
43	    static constexpr bool is_nothrow_movable = std::is_nothrow_move_constructible_v<T>;
44	    static constexpr bool is_nothrow_destructible = std::is_nothrow_destructible_v<T>;
45	
46	    // Basic SBO eligibility (compile-time check)
47	    static constexpr bool is_sbo_eligible = is_small_enough &&
48	                                           is_aligned_properly &&
49	                                           is_nothrow_movable &&
50	                                           is_nothrow_destructible;
51	
52	    // Always use SBO for very small types
53	    static constexpr bool always_sbo = sizeof(T) <= SBOConfig::ALWAYS_SBO_SIZE && is_sbo_eligible;
54	
55	    // Conditional SBO for medium-sized types
56	    static constexpr bool conditional_sbo = sizeof(T) <= SBOConfig::CONDITIONAL_SBO_SIZE &&
57	                                           sizeof(T) > SBOConfig::ALWAYS_SBO_SIZE &&
58	                                           is_sbo_eligible;
59	
60	    // Force heap allocation for large or problematic types
61	    static constexpr bool force_heap = !is_sbo_eligible || sizeof(T) > SBOConfig::MAX_SBO_SIZE;
62	};
63	
64	/**
65	 * @brief Specializations for common types to override default behavior.
66	 */
67	template<>
68	struct SBOTraits<std::string> {
69	    static constexpr bool is_sbo_eligible = false;
70	    static constexpr bool always_sbo = false;
71	    static constexpr bool conditional_sbo = false;
72	    static constexpr bool force_heap = true;
73	};
74	
75	template<typename T, typename Alloc>
76	struct SBOTraits<std::vector<T, Alloc>> {
77	    static constexpr bool is_sbo_eligible = false;
78	    static constexpr bool always_sbo = false;
79	    static constexpr bool conditional_sbo = false;
80	    static constexpr bool force_heap = true;
81	};
82	
83	template<typename Key, typename Value, typename Hash, typename Equal, typename Alloc>
84	struct SBOTraits<std::unordered_map<Key, Value, Hash, Equal, Alloc>> {
85	    static constexpr bool is_sbo_eligible = false;
86	    static constexpr bool always_sbo = false;
87	    static constexpr bool conditional_sbo = false;
88	    static constexpr bool force_heap = true;
89	};
