#include <type_traits>

namespace test_reaction {

struct VoidResourceSnapshot {
    bool retrievedIsVoid;
    bool usesSboStorage;
    bool nameAssigned;
    bool nameClearedAfterClose;
};

inline VoidResourceSnapshot test_resource_void_behavior(const std::string &nodeName) {
    // 1. Create shared Resource<Void> instance
    auto voidResource = std::make_shared<reaction::Resource<reaction::Void>>();

    // 2. Check if resource uses SBO storage
    bool usesSboStorage = voidResource->isUsingSBO();

    // 3. Get value from resource
    auto value = voidResource->getValue();

    // 4. Check if retrieved value is Void type
    bool retrievedIsVoid = std::is_same_v<decltype(value), reaction::Void>;

    // 5. Get observer graph instance
    auto &graph = reaction::ObserverGraph::getInstance();

    // 6. Register resource node
    graph.addNode(voidResource);

    // 7. Assign node name
    graph.setName(voidResource, nodeName);

    // 8. Check if name was assigned
    std::string assignedName = graph.getName(voidResource);
    bool nameAssigned = (assignedName == nodeName);

    // 9. Close node
    graph.closeNode(voidResource);

    // 10. Check if name was cleared after close
    std::string nameAfterClose = graph.getName(voidResource);
    bool nameClearedAfterClose = nameAfterClose.empty();

    // 11. Return void resource snapshot
    return VoidResourceSnapshot{
        retrievedIsVoid,
        usesSboStorage,
        nameAssigned,
        nameClearedAfterClose
    };
}

}  // namespace test_reaction
```

