61	/**
62	 * @brief Traditional heap-based resource implementation.
63	 *
64	 * This is the fallback implementation when SBO is not beneficial or disabled.
65	 */
66	template <typename Type>
67	class ResourceImpl : public ObserverNode {
68	public:
69	    /**
70	     * @brief Default constructor initializes with nullptr.
71	     */
72	    ResourceImpl() : m_ptr(nullptr) {
73	    }
74	
75	    /**
76	     * @brief Constructor that initializes the resource with a forwarded value.
77	     *
78	     * @tparam T Type of the initialization argument, constrained so it cannot be another Resource<Type>.
79	     * @param t The initialization value for the resource.
80	     */
81	    template <typename T>
82	        requires(!std::is_same_v<std::remove_cvref_t<T>, ResourceImpl<Type>>)
83	    ResourceImpl(T &&t) : m_ptr(std::make_unique<Type>(std::forward<T>(t))) {
84	    }
85	
86	    // Delete copy constructor to avoid copying unique_ptr
87	    ResourceImpl(const ResourceImpl &) = delete;
88	
89	    // Delete copy assignment operator to avoid copying unique_ptr
90	    ResourceImpl &operator=(const ResourceImpl &) = delete;
91	
92	    /**
93	     * @brief Get a copy of the managed resource value in a thread-safe manner.
94	     *
95	     * Throws std::runtime_error if the resource is not initialized.
96	     *
97	     * @return Type Copy of the managed resource.
98	     */
99	    [[nodiscard]] Type getValue() const {
100	        ConditionalSharedLock<ConditionalSharedMutex> lock(m_resourceMutex);
101	        if (!m_ptr) {
102	            REACTION_THROW_RESOURCE_NOT_INITIALIZED("Resource");
103	        }
104	        return *m_ptr;
105	    }
106	
107	    /**
108	     * @brief Update the managed resource with a new value.
109	     *
110	     * If the resource is not yet initialized, create a new one with the forwarded value.
111	     * Otherwise, assign the forwarded value to the existing resource.
112	     *
113	     * @tparam T Type of the new value to update with.
114	     * @param t The new value.
115	     * @return true if the value changed.
116	     */
117	    template <typename T>
118	    bool updateValue(T &&t) noexcept {
119	        REACTION_REGISTER_THREAD();
120	        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_resourceMutex);
121	        bool changed = true;
122	        if (!m_ptr) {
123	            m_ptr = std::make_unique<Type>(std::forward<T>(t));
124	        } else {
125	            if constexpr (ComparableType<Type>) {
126	                // Create a local copy to avoid data tearing during comparison
127	                Type newValue(std::forward<T>(t));
128	                changed = *m_ptr != newValue;
129	                if (changed) {
130	                    *m_ptr = std::move(newValue);
131	                }
132	            } else {
133	                *m_ptr = std::forward<T>(t);
134	            }
135	        }
136	        return changed;
137	    }
138	
139	    /**
140	     * @brief Get the raw pointer to the managed resource.
141	     *
142	     * Throws std::runtime_error if the resource is not initialized.
143	     *
144	     * @return Type* Raw pointer to the resource.
145	     */
146	    [[nodiscard]] Type *getRawPtr() const {
147	        ConditionalSharedLock<ConditionalSharedMutex> lock(m_resourceMutex);
148	        if (!this->m_ptr) {
149	            REACTION_THROW_NULL_POINTER("resource pointer access");
150	        }
