163	        REACTION_REGISTER_THREAD();
164	        bool changed = false;
165	        {
166	            ConditionalUniqueLock<ConditionalSharedMutex> lock(m_resourceMutex);
167	            try {
168	                // Direct access to avoid lock recursion
169	                if (!m_ptr) {
170	                    REACTION_THROW_RESOURCE_NOT_INITIALIZED("ResourceImpl");
171	                }
172	
173	                changed = operation(*m_ptr);
174	
175	                if (alwaysChanged) {
