44	/**
45	 * @brief Unified base class for cache implementations with common functionality.
46	 *
47	 * This template class provides common caching patterns including:
48	 * - Version-based cache invalidation
49	 * - LRU-based cleanup with TTL
50	 * - Thread-safe operations
51	 * - Statistics tracking
52	 *
53	 * @tparam Key Cache key type
54	 * @tparam Value Cache value type
55	 * @tparam Hash Hash function for key type
56	 * @tparam KeyEqual Equality comparison for key type
57	 */
58	template <
59	    typename Key,
60	    typename Value,
61	    typename Hash = std::hash<Key>,
62	    typename KeyEqual = std::equal_to<Key>>
63	class CacheBase {
64	public:
65	    /**
66	     * @brief Cache statistics structure.
67	     */
68	    struct Stats {
69	        size_t totalEntries = 0;
70	        uint64_t currentVersion = 0;
71	        size_t hitCount = 0;
72	        size_t missCount = 0;
73	        double hitRatio = 0.0;
74	
75	        Stats(size_t entries, uint64_t version, size_t hits, size_t misses)
76	            : totalEntries(entries), currentVersion(version), hitCount(hits), missCount(misses), hitRatio(hits + misses > 0 ? static_cast<double>(hits) / (hits + misses) : 0.0) {}
77	    };
78	
79	    /**
80	     * @brief Cache entry wrapper with metadata.
81	     */
82	    struct CacheEntry {
83	        Value value;
84	        uint64_t version;
85	        mutable std::chrono::steady_clock::time_point lastAccess;
86	
87	        template <typename V>
88	        CacheEntry(V &&val, uint64_t ver)
89	            : value(std::forward<V>(val)), version(ver), lastAccess(std::chrono::steady_clock::now()) {}
90	
91	        CacheEntry(const CacheEntry &other)
92	            : value(other.value), version(other.version), lastAccess(other.lastAccess) {}
93	
94	        CacheEntry(CacheEntry &&other) noexcept
95	            : value(std::move(other.value)), version(other.version), lastAccess(other.lastAccess) {}
96	
97	        CacheEntry &operator=(const CacheEntry &other) {
98	            if (this != &other) {
99	                value = other.value;
100	                version = other.version;
101	                lastAccess = other.lastAccess;
102	            }
103	            return *this;
104	        }
105	
106	        CacheEntry &operator=(CacheEntry &&other) noexcept {
107	            if (this != &other) {
108	                value = std::move(other.value);
109	                version = other.version;
110	                lastAccess = other.lastAccess;
111	            }
112	            return *this;
113	        }
114	    };
115	
116	protected:
117	    /**
118	     * @brief Constructor with cache configuration.
119	     *
120	     * @param maxSize Maximum number of entries before cleanup
121	     * @param ttl Time-to-live for cache entries
122	     */
123	    explicit CacheBase(size_t maxSize, std::chrono::minutes ttl)
124	        : m_maxCacheSize(maxSize), m_cacheTTL(ttl) {}
125	
126	    /**
127	     * @brief Try to get cached value for a key.
128	     *
129	     * @param key The key to look up
130	     * @return Pointer to cached value if valid, nullptr otherwise
131	     */
132	    const Value *getCachedValue(const Key &key) const noexcept {
133	        std::shared_lock<std::shared_mutex> lock(m_cacheMutex);
134	        auto it = m_cacheEntries.find(key);
135	
136	        if (it != m_cacheEntries.end() &&
137	            it->second.version == m_currentVersion.load(std::memory_order_acquire)) {
138	            // Update last access time (mutable)
139	            it->second.lastAccess = std::chrono::steady_clock::now();
140	            m_hitCount.fetch_add(1, std::memory_order_relaxed);
141	            return &it->second.value;
142	        }
143	
144	        m_missCount.fetch_add(1, std::memory_order_relaxed);
145	        return nullptr;
146	    }
147	
148	    /**
149	     * @brief Cache a value for a key.
150	     *
151	     * @param key The key to cache under
152	     * @param value The value to cache
153	     */
154	    template <typename V>
155	    void cacheValue(const Key &key, V &&value) noexcept {
156	        std::unique_lock<std::shared_mutex> lock(m_cacheMutex);
157	        uint64_t currentVersion = m_currentVersion.load(std::memory_order_acquire);
158	        m_cacheEntries.insert_or_assign(key, CacheEntry{std::forward<V>(value), currentVersion});
159	
160	        // Cleanup if cache is getting too large
161	        if (m_cacheEntries.size() > m_maxCacheSize) {
162	            cleanupOldEntriesInternal();
163	        }
164	    }
165	
166	    /**
167	     * @brief Invalidate all cache entries due to structural change.
168	     */
169	    void invalidateAllEntries() noexcept {
170	        std::unique_lock<std::shared_mutex> lock(m_cacheMutex);
171	        // Simply increment version - old entries will be automatically ignored
172	        m_currentVersion.fetch_add(1, std::memory_order_release);
173	
174	        // Optionally clear cache entries to free memory immediately
175	        m_cacheEntries.clear();
176	    }
177	
178	    /**
179	     * @brief Get current cache version.
180	     */
181	    uint64_t getCurrentVersion() const noexcept {
182	        return m_currentVersion.load(std::memory_order_acquire);
183	    }
184	
185	    /**
186	     * @brief Get cache statistics.
187	     */
188	    Stats getStatsInternal() const noexcept {
189	        std::shared_lock<std::shared_mutex> lock(m_cacheMutex);
190	        return Stats{
191	            m_cacheEntries.size(),
192	            m_currentVersion.load(std::memory_order_acquire),
193	            m_hitCount.load(std::memory_order_relaxed),
194	            m_missCount.load(std::memory_order_relaxed)};
195	    }
