208	     * Must be called with m_cacheMutex held in exclusive mode.
209	     */
210	    void cleanupOldEntriesInternal() noexcept {
211	        auto now = std::chrono::steady_clock::now();
212	        auto cutoffTime = now - m_cacheTTL;
213	
214	        // Remove entries older than TTL
215	        for (auto it = m_cacheEntries.begin(); it != m_cacheEntries.end();) {
216	            if (it->second.lastAccess < cutoffTime) {
217	                it = m_cacheEntries.erase(it);
218	            } else {
219	                ++it;
220	            }
221	        }
