#pragma once

#include <reaction/reaction.h>
#include <reaction/expression/expression_builders.h>

namespace test_reaction {

/**
 * Struct: RawExpressionSnapshot
 *
 * Captures the values produced by raw expression builder helpers
 * (`make_binary_expr`, `make_unary_expr`) before and after updating
 * their reactive inputs.
 */
struct RawExpressionSnapshot {
    int initialSum;
    int initialNegatedSum;
    int initialChainedValue;

    int updatedSum;
    int updatedNegatedSum;
    int updatedChainedValue;
};

/**
 * Function: test_raw_expression_builders
 *
 * Demonstrates how low-level expression builder helpers
 * (`make_binary_expr`, `make_unary_expr`) can be combined with
 * `expr` to build reactive calculations without using the higher
 * level `make_binary_op` / `make_unary_op` shortcuts.
 *
 * The function:
 * - Creates three reactive integers A, B, C.
 * - Builds sum = A + B via make_binary_expr.
 * - Builds negated = -(A + B) via make_unary_expr(make_binary_expr(...)).
 * - Builds chained = -(A + B) * C via nested make_* calls.
 * - Updates A and C and records all expression values before and after.
 *
 * @param a Initial value for the first input
 * @param b Initial value for the second input
 * @param c Initial value for the chaining multiplier
 * @return RawExpressionSnapshot
 *         Snapshot of sum / negated / chained values before and after updates.
 */
inline RawExpressionSnapshot test_raw_expression_builders(int a, int b, int c) {
    using namespace reaction;

    // Step 1: Create reactive variables
    auto A = var(a);
    auto B = var(b);
    auto C = var(c);

    // Step 2: Build sum expression using make_binary_expr
    // sum = A + B
    auto sumExpr = make_binary_expr<AddOp>(A, B);
    auto sum = expr(sumExpr);

    // Step 3: Build negated expression using make_unary_expr on a binary expression
    // negated = -(A + B)
    auto negatedExpr = make_unary_expr<NegOp>(make_binary_expr<AddOp>(A, B));
    auto negated = expr(negatedExpr);

    // Step 4: Build chained expression
    // chained = -(A + B) * C
    auto chainedExpr = make_binary_expr<MulOp>(
        make_unary_expr<NegOp>(make_binary_expr<AddOp>(A, B)),
        C
    );
    auto chained = expr(chainedExpr);

    // Step 5: Get initial expression values
    RawExpressionSnapshot snapshot;
    snapshot.initialSum = sum.get();
    snapshot.initialNegatedSum = negated.get();
    snapshot.initialChainedValue = chained.get();

    // Step 6: Update variables to trigger recomputation
    A.value(a + 10);
    C.value(c + 5);

    // Step 7: Get updated expression values
    snapshot.updatedSum = sum.get();
    snapshot.updatedNegatedSum = negated.get();
    snapshot.updatedChainedValue = chained.get();

    // Step 8: Return raw expression snapshot
    return snapshot;
}

}  // namespace test_reaction
```

This implementation:

1. **Creates reactive variables** using `var()` for A, B, and C
2. **Builds sum expression** using `make_binary_expr<AddOp>(A, B)` to create A + B, then wraps it with `expr()`
3. **Builds negated expression** using `make_unary_expr<NegOp>()` around a `make_binary_expr<AddOp>()` to create -(A + B)
4. **Builds chained expression** using nested `make_binary_expr` and `make_unary_expr` to create -(A + B) * C
5. **Gets initial values** using the `.get()` method on each reactive expression
6. **Updates variables** using `.value()` to trigger reactive recomputation
7. **Gets updated values** after the reactive propagation
8. **Returns the snapshot** with all the captured values

The implementation uses the low-level `make_binary_expr` and `make_unary_expr` functions with explicit operator types (`AddOp`, `NegOp`, `MulOp`) instead of using operator overloads or the higher-level `make_binary_op`/`make_unary_op` helpers.

